#' Circos Chord Diagram
#'
#' Draws a circular chord diagram visualizing the flow or co-occurrence 
#' between categories - for example transitions between disease states, 
#' co-mutation of genes, referral patterns between sites, or migration between 
#' diagnostic categories. Each category occupies a sector on a circle and 
#' ribbons connect categories with a width proportional to the strength of 
#' their relationship. Input may be an edge list (from / to / value) or the 
#' two categorical variables whose cross-tabulation defines the links. Built 
#' on the circlize package.
#' 
#'
#' @examples
#' \donttest{
#' circos(
#'     data = mydata,
#'     fromVar = "referring_site",
#'     toVar = "treating_site",
#'     valueVar = "n_patients")
#'}
#' @param data The data as a data frame.
#' @param inputMode Whether links are given as an edge list with an optional
#'   value column, or derived by cross-tabulating two categorical variables.
#' @param fromVar Source category for each link.
#' @param toVar Target category for each link.
#' @param valueVar Link weight (edge-list mode). If omitted, each row counts
#'   as 1 and identical from/to pairs are summed.
#' @param directional Draw ribbons with directionality (arrows from source to
#'   target).
#' @param symmetric Treat the relationship as undirected (combine A->B and
#'   B->A). Useful for co-occurrence such as co-mutation.
#' @param gridPalette Colour palette for the category sectors.
#' @param transparency Transparency of the connecting ribbons (0 = opaque,
#'   higher = more transparent).
#' @param showLabels Label each category sector.
#' @param showMatrix Report the from-to matrix underlying the diagram.
#' @param showExplanation Display an explanation of the chord diagram.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$matrixTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$matrixTable$asDF}
#'
#' \code{as.data.frame(results$matrixTable)}
#'
#' @export
circos <- function(
    data,
    inputMode = "edges",
    fromVar,
    toVar,
    valueVar = NULL,
    directional = TRUE,
    symmetric = FALSE,
    gridPalette = "Set2",
    transparency = 0.5,
    showLabels = TRUE,
    showMatrix = TRUE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("circos requires jmvcore to be installed (restart may be required)")

    if ( ! missing(fromVar)) fromVar <- jmvcore::resolveQuo(jmvcore::enquo(fromVar))
    if ( ! missing(toVar)) toVar <- jmvcore::resolveQuo(jmvcore::enquo(toVar))
    if ( ! missing(valueVar)) valueVar <- jmvcore::resolveQuo(jmvcore::enquo(valueVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(fromVar), fromVar, NULL),
            `if`( ! missing(toVar), toVar, NULL),
            `if`( ! missing(valueVar), valueVar, NULL))


    options <- circosOptions$new(
        inputMode = inputMode,
        fromVar = fromVar,
        toVar = toVar,
        valueVar = valueVar,
        directional = directional,
        symmetric = symmetric,
        gridPalette = gridPalette,
        transparency = transparency,
        showLabels = showLabels,
        showMatrix = showMatrix,
        showExplanation = showExplanation)

    analysis <- circosClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

